// Checks the request. client_id selects the chain the run is logged in.
const s = $('Settings').first().json;
const body = $('Agent request').first().json.body || {};
const clientId = String(body.client_id ?? '').trim();
const prompt = typeof body.prompt === 'string' ? body.prompt : '';
const list = (v) => String(v || '').split(',').map((x) => x.trim()).filter(Boolean);
const runId = `${$execution.id}-${Math.random().toString(36).slice(2, 8)}`;

let route = 'run';
let http = 200;
let error = '';
if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(clientId)) {
  route = 'bad'; http = 400; error = 'client_id is required: 1-64 letters, digits, dots, dashes or underscores';
} else if (list(s.allowed_clients).length && !list(s.allowed_clients).includes(clientId)) {
  route = 'bad'; http = 403; error = 'client_id is not in allowed_clients';
} else if (list(s.paused_clients).includes(clientId)) {
  route = 'refuse'; http = 403; error = 'this client is paused';
} else if (!prompt.trim()) {
  route = 'refuse'; http = 422; error = 'prompt is empty';
} else if (prompt.length > s.max_prompt_chars) {
  route = 'refuse'; http = 422; error = `prompt is longer than ${s.max_prompt_chars} characters`;
}
return [{ json: { route, http, error, client_id: clientId, prompt, run_id: runId } }];

// ---- SHA-256 and the entry hash (keep identical in every Code node) ----
// Uses Node's crypto module when the instance allows it (n8n Cloud does),
// otherwise a small pure-JavaScript SHA-256 that gives the identical result.
function sha256Hex(text) {
  try {
    return require('crypto').createHash('sha256').update(text, 'utf8').digest('hex');
  } catch (e) {
    return sha256Fallback(text);
  }
}

