// ---- turn the run (answer, agent error or refusal) into a log entry ----
const s = $('Settings').first().json;
const req = $('Validate request').first().json;
const j = $input.first().json;
const clip = (t) => (s.store_text ? String(t).slice(0, Number(s.store_text_max_chars) || 0) : '');

let outcome;
let answer = '';
let error = '';
let toolCalls = -1;
let modelCalls = -1;
if (j.route === 'refuse') {
  outcome = 'refused';
  error = req.error;
  toolCalls = 0;
  modelCalls = 0;
} else if (typeof j.output === 'string' && !j.error) {
  outcome = 'ok';
  answer = j.output;
  const steps = Array.isArray(j.intermediateSteps) ? j.intermediateSteps : [];
  toolCalls = steps.length;
  // Tool calls that came from the same model reply share its log text.
  const replies = new Set(steps.map((st, i) => {
    const m = st?.action?.messageLog?.[0];
    return m?.id || m?.kwargs?.id || st?.action?.log || `step-${i}`;
  }));
  modelCalls = replies.size + 1;
} else {
  outcome = 'error';
  const e = j.error;
  error = String((e && (e.message || e.description)) || e || 'The agent failed').slice(0, 300);
}

return [{
  json: {
    client_id: req.client_id,
    run_id: req.run_id,
    model: String(s.model),
    outcome,
    prompt_sha256: sha256Hex(req.prompt),
    answer_sha256: outcome === 'ok' ? sha256Hex(answer) : '',
    model_calls: modelCalls,
    tool_calls: toolCalls,
    error,
    prompt_text: clip(req.prompt),
    answer_text: outcome === 'ok' ? clip(answer) : '',
    answer,
    http: outcome === 'ok' ? 200 : outcome === 'error' ? 502 : req.http,
  },
}];

