// ---- link the new entry to the newest entry of this client's chain ----
const e = $('Build the log entry').first().json;
const failed = $input.all().find((i) => i.json && i.json.error && i.json.id === undefined);
if (failed) throw new Error(`Could not read agent_run_log: ${failed.json.error.message || failed.json.error}`);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);

let prev_hash = GENESIS;
let seq = 1;
if (rows.length) {
  const maxSeq = Math.max(...rows.map((r) => Number(r.seq)));
  const top = rows.filter((r) => Number(r.seq) === maxSeq);
  if (top.length === rows.length && rows.length >= 50) throw new Error('Too many parallel entries share the newest seq');
  // If parallel runs wrote the same seq, the one with the lowest row id is the real one.
  const head = top.reduce((a, b) => (Number(a.id) < Number(b.id) ? a : b));
  if (!/^[0-9a-f]{64}$/.test(String(head.entry_hash))) {
    throw new Error(`The newest entry of ${e.client_id} (seq ${maxSeq}) has no valid entry_hash. Check the chain before logging more.`);
  }
  prev_hash = head.entry_hash;
  seq = maxSeq + 1;
}

const entry = {
  client_id: e.client_id, seq, run_id: e.run_id, logged_at: new Date().toISOString(), model: e.model,
