const attempt = $runIndex + 1;
const decision = confirmed ? 'confirmed' : (attempt < Number(s.max_log_attempts) ? 'retry' : 'give_up');

const receipt = {
  client_id: mine.client_id, seq: mine.seq, run_id: mine.run_id, logged_at: mine.logged_at, outcome: mine.outcome,
  prompt_sha256: mine.prompt_sha256, answer_sha256: mine.answer_sha256,
  prev_hash: mine.prev_hash, entry_hash: mine.entry_hash,
};
let body;
if (mine.outcome === 'ok') body = { answer: e.answer, receipt };
else if (mine.outcome === 'error') body = { error: 'agent_failed', message: 'The agent run failed. The failure was logged.', receipt };
else body = { error: 'refused', message: mine.error, receipt };

return [{ json: { decision, attempt, row_id: myId, http: e.http, body } }];

